 94  	static class PropertiesLogger implements ApplicationListener<ApplicationPreparedEvent> {
 95  
 96  		private static final Log log = LogFactory.getLog(PropertiesLogger.class);
 97  
 98  		private ConfigurableEnvironment environment;
 99  
100  		private boolean isFirstRun = true;
101  
102  		@Override
103  		public void onApplicationEvent(ApplicationPreparedEvent event) {
104  			if (isFirstRun) {
105  				environment = event.getApplicationContext().getEnvironment();
106  				printProperties();
107  			}
108  			isFirstRun = false;
109  		}
110  
111  		public void printProperties() {
112  			for (EnumerablePropertySource<?> source : findPropertiesPropertySources()) {
113  				log.info("PropertySource: " + source.getName());
114  				String[] names = source.getPropertyNames();
115  				Arrays.sort(names);
116  				for (String name : names) {
117  					String resolved = environment.getProperty(name);
118  					String a = System.getProperty("abc");
119  
120  					assertNotNull(resolved, "resolved environment property: " + name + " is null.");
121  
122  					Object sourceProperty = source.getProperty(name);
123  
124  					assertNotNull(sourceProperty, "source property was expecting an object but is null.");
125  
126  					assertNotNull(sourceProperty.toString(), "source property toString() returned null.");
127  
128  					String value = sourceProperty.toString();
129  					if (resolved.equals(value)) {
130  						log.info(name + "=" + resolved);
131  					}
132  					else {
133  						log.info(name + "=" + value + " OVERRIDDEN to " + resolved);
134  					}
135  				}
136  			}
137  		}
138  
139  		private List<EnumerablePropertySource<?>> findPropertiesPropertySources() {
140  			List<EnumerablePropertySource<?>> sources = new LinkedList<>();
141  			for (PropertySource<?> source : environment.getPropertySources()) {
142  				if (source instanceof EnumerablePropertySource enumerable) {
143  					sources.add(enumerable);
144  				}
145  			}
146  			return sources;
147  		}
148  
149  	}
150  
151  }

