64  
65  	@Test
66  	void testTriggerExceptionJson() {
67  		ResponseEntity<Map<String, Object>> resp = rest.exchange(
68  				RequestEntity.get("http://localhost:" + port + "/oups").build(),
69  				new ParameterizedTypeReference<Map<String, Object>>() {
70  				});
71  		assertThat(resp).isNotNull();
72  		assertThat(resp.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
73  		assertThat(resp.getBody()).containsKey("timestamp");
74  		assertThat(resp.getBody()).containsKey("status");
75  		assertThat(resp.getBody()).containsKey("error");
76  		assertThat(resp.getBody()).containsEntry("message",
77  				"Expected: controller used to showcase what happens when an exception is thrown");
78  		assertThat(resp.getBody()).containsEntry("path", "/oups");
79  	}
80  
81  	@Test
82  	void testTriggerExceptionHtml() {
83  		HttpHeaders headers = new HttpHeaders();
84  		headers.setAccept(List.of(MediaType.TEXT_HTML));
85  		ResponseEntity<String> resp = rest.exchange("http://localhost:" + port + "/oups", HttpMethod.GET,
86  				new HttpEntity<>(headers), String.class);
87  		assertThat(resp).isNotNull();
88  		assertThat(resp.getStatusCode()).isEqualTo(HttpStatus.INTERNAL_SERVER_ERROR);
89  		assertThat(resp.getBody()).isNotNull();
90  		// html:
91  		assertThat(resp.getBody()).containsSubsequence("<body>", "<h2>", "Something happened...", "</h2>", "<p>",
92  				"Expected:", "controller", "used", "to", "showcase", "what", "happens", "when", "an", "exception", "is",
93  				"thrown", "</p>", "</body>");
94  		// Not the whitelabel error page:
95  		assertThat(resp.getBody()).doesNotContain("Whitelabel Error Page",
96  				"This application has no explicit mapping for");
97  	}
